application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
  min-width: 280px;
}

.app-shell {
  width: min(100% - 2rem, 720px);
  margin: 0 auto;
  padding: 3rem 0;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #315ca8;
  font-size: .8rem;
  font-weight: 750;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.intro {
  max-width: 42rem;
  margin-bottom: 0;
  color: #526078;
}

.todo-panel {
  margin-bottom: 1.25rem;
  padding: clamp(1.1rem, 4vw, 1.6rem);
  border: 1px solid #d6deea;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 5px 18px rgb(28 49 84 / 7%);
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1 1 auto;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-weight: 650;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: .6rem .75rem;
  border: 1px solid #9baac0;
  border-radius: 7px;
  color: #172033;
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  border: 0;
  border-radius: 7px;
  padding: .6rem 1rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.primary-button {
  color: #fff;
  background: #2457a6;
}

.primary-button:hover {
  background: #1b4384;
}

.form-message {
  min-height: 1.5em;
  margin: .5rem 0 0;
  color: #a32929;
  font-size: .9rem;
}

.list-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.list-heading h2 {
  margin-bottom: 0;
}

.count-summary {
  margin-bottom: 0;
  color: #526078;
  font-size: .95rem;
}

.count-summary span {
  color: #172033;
  font-weight: 750;
}

.task-list {
  display: grid;
  gap: .7rem;
  margin: 1.2rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .8rem .9rem;
  border: 1px solid #d6deea;
  border-radius: 8px;
  background: #f9fbfd;
}

.task-toggle {
  flex: 0 0 auto;
  width: 1.15rem;
  height: 1.15rem;
  accent-color: #2457a6;
}

.task-text {
  flex: 1 1 auto;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: #5b687b;
  text-decoration: line-through;
}

.delete-button {
  min-height: 2.25rem;
  padding: .4rem .7rem;
  color: #8c2020;
  background: #fcecec;
}

.delete-button:hover {
  background: #f7dada;
}

.empty-state {
  margin: 1.2rem 0 0;
  color: #526078;
  text-align: center;
}

:focus-visible {
  outline: 3px solid #f0a51a;
  outline-offset: 2px;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 2rem 0;
  }

  .input-row {
    align-items: stretch;
    flex-direction: column;
  }

  .primary-button {
    width: 100%;
  }

  .list-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: .25rem;
  }
}

