const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const emptyState = document.querySelector('#empty-state');
const taskError = document.querySelector('#task-error');

let tasks = [];
let nextTaskId = 1;

function setError(message) {
  taskError.textContent = message;
}

function addTask(text) {
  tasks.push({ id: nextTaskId, text, completed: false });
  nextTaskId += 1;
}

function createTaskElement(task) {
  const item = document.createElement('li');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);
  if (task.completed) item.classList.add('completed');

  const toggleLabel = document.createElement('label');
  toggleLabel.className = 'visually-hidden';
  toggleLabel.htmlFor = `task-toggle-${task.id}`;
  toggleLabel.textContent = `Mark ${task.text} as complete`;

  const toggle = document.createElement('input');
  toggle.type = 'checkbox';
  toggle.id = `task-toggle-${task.id}`;
  toggle.className = 'task-toggle';
  toggle.dataset.testid = 'task-complete';
  toggle.checked = task.completed;
  toggle.setAttribute('aria-label', `Mark ${task.text} as complete`);
  toggle.addEventListener('change', () => {
    task.completed = toggle.checked;
    renderTasks();
  });

  const text = document.createElement('span');
  text.className = 'task-text';
  text.dataset.testid = 'task-text';
  text.textContent = task.text;

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-button';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
  deleteButton.addEventListener('click', () => {
    tasks = tasks.filter((currentTask) => currentTask.id !== task.id);
    renderTasks();
  });

  item.append(toggle, toggleLabel, text, deleteButton);
  return item;
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  incompleteCount.textContent = String(tasks.filter((task) => !task.completed).length);
  emptyState.hidden = tasks.length > 0;
}

function handleTaskSubmit(event) {
  event.preventDefault();
  const text = taskInput.value.trim();
  if (!text) {
    setError('Enter a task before adding it.');
    taskInput.focus();
    return;
  }
  addTask(text);
  taskInput.value = '';
  setError('');
  renderTasks();
  taskInput.focus();
}

taskForm.addEventListener('submit', handleTaskSubmit);
renderTasks();
